def _remote_project(repo_url):
    value = str(repo_url or "").strip()
    if value.startswith("git@") and ":" in value:
        path = value.split(":", 1)[1]
    else:
        path = urlparse(value).path.lstrip("/")
    return path.removesuffix(".git").strip("/")


def _encrypt_secret(secret):
    digest = hashlib.sha256(settings.SECRET_KEY.encode("utf-8")).digest()
    cipher = Fernet(base64.urlsafe_b64encode(digest))
    payload = json.dumps(
        {"secret": secret or "", "password": ""},
        ensure_ascii=False,
        separators=(",", ":"),
    ).encode("utf-8")
    return cipher.encrypt(payload)


def migrate_legacy_repository(apps, schema_editor):
    """将旧的单仓库系统配置转换为仓库记录，供已有项目绑定使用。"""

    PytestProduct = apps.get_model("auto_pytest", "PytestProduct")
    if not PytestProduct.objects.using(schema_editor.connection.alias).exists():
        return

    CacheData = apps.get_model("auto_system", "CacheData")
    PytestRepository = apps.get_model("auto_pytest", "PytestRepository")
    PytestRepositoryCredential = apps.get_model(
        "auto_pytest",
        "PytestRepositoryCredential",
    )
    database = schema_editor.connection.alias
    keys = {
        "PYTEST_GIT_URL",
        "PYTEST_GIT_PROVIDER",
        "PYTEST_GIT_API_BASE_URL",
        "PYTEST_GIT_ACCESS_TOKEN",
        "PYTEST_GIT_DEFAULT_BRANCH",
    }
    config = dict(
        CacheData.objects.using(database)
        .filter(key__in=keys)
        .values_list("key", "value")
    )
    repo_url = str(config.get("PYTEST_GIT_URL") or "").strip()
    remote_project = _remote_project(repo_url)
    if not repo_url or not remote_project:
        raise RuntimeError(
            "检测到已有 Pytest 项目，但旧版 PYTEST_GIT_URL 未配置，"
            "请先补全旧版仓库地址后重新执行迁移"
        )

    credential = None
    access_token = str(config.get("PYTEST_GIT_ACCESS_TOKEN") or "").strip()
    if access_token:
        credential = (
            PytestRepositoryCredential.objects.using(database)
            .filter(repository__id=1)
            .first()
        )
        if credential is None:
            credential = PytestRepositoryCredential.objects.using(database).create(
                auth_type="token",
                secret_ciphertext=_encrypt_secret(access_token),
                key_version="fernet-sha256-v1",
            )

    repository_defaults = {
        "name": "默认 Pytest 仓库",
        "provider": str(config.get("PYTEST_GIT_PROVIDER") or "gitlab").strip(),
        "repo_url": repo_url,
        "api_base_url": str(config.get("PYTEST_GIT_API_BASE_URL") or "").strip() or None,
        "remote_project": remote_project,
        "default_branch": str(config.get("PYTEST_GIT_DEFAULT_BRANCH") or "master").strip(),
        "active_branch": str(config.get("PYTEST_GIT_DEFAULT_BRANCH") or "master").strip(),
    }
    if credential is not None:
        repository_defaults["credential"] = credential

    PytestRepository.objects.using(database).update_or_create(
        id=1,
        defaults=repository_defaults,
    )


